oxy_webhelp_navlinks = {"mv_set_up_protection-d39307e49421":{"topics":[{"title":"Backup script settings for SLA Managed Volumes","shortdesc":"<p class=\"shortdesc\">Information about backup script settings for SLA Managed Volumes creation, including         details on host script execution and pre-backup and post-backup commands.<\/p>","href":"managedvolumes\/mv_backup_script_settings.html","attributes":{"data-id":"mv_backup_script_settings"},"menu":{"hasChildren":false},"tocID":"mv_backup_script_settings-d39307e49432","topics":[]},{"title":"Scripted backups for snapshots with assigned SLA Domains","shortdesc":"<p class=\"shortdesc\">Client-side scripted backups interact with the assigned SLA Domain to control how         frequently the Rubrik cluster creates and retains snapshots for a Managed         Volume.<\/p>","href":"managedvolumes\/mv_scripted_backups_snapshots_assigned_sla_domain.html","attributes":{"data-id":"mv_scripted_backups_snapshots_assigned_sla_domain"},"menu":{"hasChildren":false},"tocID":"mv_scripted_backups_snapshots_assigned_sla_domain-d39307e49443","topics":[]},{"title":"Custom SLA Domains for SLA Managed Volumes","shortdesc":"<p class=\"shortdesc\">SLA Domains for SLA Managed Volumes are customized based on backup         requirements.<\/p>","href":"managedvolumes\/mv_custom_sla_domains_sla_managed_volumes.html","attributes":{"data-id":"mv_custom_sla_domains_sla_managed_volumes"},"menu":{"hasChildren":false},"tocID":"mv_custom_sla_domains_sla_managed_volumes-d39307e49454","topics":[]},{"title":"Assigning SLA Domains to Managed Volumes and SLA Managed Volumes","shortdesc":"<p class=\"shortdesc\">Assign an SLA Domain to the Managed Volume or SLA Managed Volume snapshots to provide         policy-based management.<\/p>","href":"managedvolumes\/mv_assigning_sla_domain.html","attributes":{"data-id":"mv_assigning_sla_domain"},"menu":{"hasChildren":false},"tocID":"mv_assigning_sla_domain-d39307e49465","topics":[]}]}};